// Rapid Percentage & Reversal Formula
// x% of y == y% of x
const quickPercent = (percent: number, total: number) => (percent * total) / 100;
// 18% of 50 AED -> 50% of 18 AED = 9 AED
console.log(quickPercent(18, 50)); // 9

function computeEconomics(cost: number, sellPrice: number) {
  const profit = sellPrice - cost;
  const markup = (profit / cost) * 100;
  const margin = (profit / sellPrice) * 100;
  return { profit, markup: `${markup}%`, margin: `${margin}%` };
}
// Cost: 60 AED, Sells: 100 AED -> Markup: 66.67%, Margin: 40%

// Compound Interest Engine
function calculateCompounding(principal: number, annualRate: number, years: number, n: number = 12) {
  const total = principal * Math.pow(1 + (annualRate / n), n * years);
  return Number(total.toFixed(2));
}
// 10,000 AED invested at 8% annual return for 30 years compounded monthly:
console.log(calculateCompounding(10000, 0.08, 30)); // 109,357.30 AED (10.9x growth!)

// Doubling Time Calculator
const yearsToDouble = (annualRatePercent: number) => 72 / annualRatePercent;
console.log(`At 8% return: money doubles every ${yearsToDouble(8)} years`); // 9 years

// Expected Value Calculator
interface Outcome { probability: number; payoff: number; }
function calculateEV(outcomes: Outcome[]): number {
  return outcomes.reduce((sum, o) => sum + (o.probability * o.payoff), 0);
}
const coinBet = [
  { probability: 0.5, payoff: 200 }, // Win 200 AED
  { probability: 0.5, payoff: -100 }  // Lose 100 AED
];
console.log(calculateEV(coinBet)); // +50 AED expected profit per flip

